<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<my-tab bgColor="#fff" :datas="tabs" :current="current" @itemClick='itemClick' />
		<scroll-view scroll-y="true" class="scroll" @scrolltolower="loadMore">
			<view class="money-items" v-if="lists.length>0">
				<view class="money-item" v-for="(item,index) in lists" :key="index">
					<image :src="item.money>0?'/static/my/money-add.png':'/static/my/money-reduce.png'" mode="widthFix" class="left-img" />
					<view class="center">
						<view class="tit">{{item.desc}}</view>
						<view class="time">{{item.add_time}}</view>
					</view>
					<view class="right">
						<text :class="{'theme':item.money<0}">{{item.money>0?('+'+item.money):item.money}}</text>
					</view>
				</view>
				<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</view>
			<view class="empty-container" v-else>
				<u-empty text="暂无相关数据" :icon="emptyIcon" />
			</view>
		</scroll-view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				tabs: [{
					name: '全部',
				}, {
					name: '收入',
				}, {
					name: '支出',
				}],
				current:0,
				type:1,
				page: 1,
				pageNum: 20,
			}
		},
		onLoad(e) {
			_this = this;
			if (e.type) {
				_this.type = Number(e.type)
			}
			_this.get_zj_list()
		},
		onReady() {
			var title = ''
			switch (this.type){
				case 1:
					title = '余额明细'
					break;
				case 2:
					title = '积分明细'
					break;
				case 3:
					title = '金豆明细'
					break;
				default:
				title = '金种子明细'
					break;
			}
			if (title) {
				uni.setNavigationBarTitle({
					title:title
				})
			}
		},
		methods: {
			itemClick(current) {
				_this.current = current
				_this.page = 1
				_this.lists = []
				_this.get_zj_list()
			},
			loadMore(){
				if(_this.hasMore){
					_this.page++
					_this.get_zj_list()
				}
			},
			async get_zj_list(){
				const params = {
					pageIndex: _this.page,
					pageSize: _this.pageNum,
					type: _this.type,
					current: _this.current,
				}
				const data = await _this.$post('port/zj_list', params)
				if(data.code==200){
					_this.lists.push(...data.result.list)
					_this.hasMore = data.result.list.length >= _this.pageNum
				}else{
					_this.hasMore = false
				}
				if (_this.load) {
					_this.load = false
				}
			}
		}
	}
</script>

<style lang="scss" scoped>
	@import "static/css/user.scss";
	.container {
		height: 100%;
		.scroll{
			height: calc(100% - 88rpx);
			.money-items{
				padding: 20rpx 20rpx 0 20rpx;
			}
		}
	}
</style>
